const entrada = items[0].json;

// Sanitiza os campos
const nome = String(entrada.nome || "").replace(/\s+/g, " ").trim();
const empresa = String(entrada.empresa || "sua empresa").replace(/\s+/g, " ").trim();
const segmento = String(entrada.segmento || "seu setor").replace(/\s+/g, " ").trim();

// Preview da mensagem (para memória e auditoria)
const mensagemCompleta = `Olá, ${nome}!

Aqui é Monteiro, diretor da BMS Consultoria Tributária.

Não sei se o amigo conseguiria me ajudar, mas acredito que podemos agregar valor com algumas novas soluções na parte tributária amigo.

Sei que o tema acaba sendo muito batido e às vezes o gestor coloca tudo no mesmo saco, mas conseguimos aprofundar algumas discussões com mais afinco sem sobrepor nenhum trabalho que esteja sendo desenvolvido internamente ou por outros parceiros.

BTW, fizemos uma análise preliminar do perfil da ${empresa} e acreditamos que pode existir uma oportunidade concreta de recuperação de créditos tributários relacionada a atualizações legislativas recentes.

Prefiro não entrar em muitos detalhes por aqui pra não tomar muito teu tempo. Será se você teria um tempinho nessa ou na próxima semana para uma conversa rápida de aproximadamente 15 minutos para apresentar o que identificamos e explicar quais oportunidades podem existir para a empresa.

Me fala depois como tá tua agenda.`;

// Memória Redis
const redisMemoryMessage = JSON.stringify({
  type: "ai",
  data: {
    content: mensagemCompleta,
    tool_calls: [],
    invalid_tool_calls: [],
    additional_kwargs: {},
    response_metadata: {}
  }
});

// Payload do WhatsApp
const body = {
  messaging_product: "whatsapp",
  to: String(entrada.telefone),
  type: "template",
  template: {
    name: "appointment", // <-- substituir pelo nome real do template
    language: {
      code: "pt_BR"
    },
    components: [
      {
        type: "body",
        parameters: [
          {
            type: "text",
            text: nome
          },
          {
            type: "text",
            text: empresa
          }
        ]
      }
    ]
  }
};

return [{
  json: {
    participant_id: entrada.id,
    telefone: entrada.telefone,
    email: entrada.email,
    nome,
    empresa,
    segmento,

    template_name: "appointment",

    // Preview da mensagem
    mensagem_completa: mensagemCompleta,

    // Compatível com Redis Chat Memory
    redis_memory_message: redisMemoryMessage,

    // Body para enviar ao WhatsApp
    resultado: body
  }
}];

parameters.messageText:
=Erro no disparo inicial (Tributário) — {{ $('Loop Over Items').first().json.nome }} ({{ $('Loop Over Items').first().json.empresa_nome }})

Motivo: {{ $json.envio_erro || 'não informado' }}
Tentativa {{ $json.envio_tentativas || '?' }} de 3. {{ Number($json.envio_tentativas) >= 3 ? 'Não vou tentar de novo: precisa de atenção manual.' : 'Tento de novo no próximo disparo.' }}

assignments.value:
={{
(raw => {
  let t = (raw || "").toString().replace(/\s+/g, "").replace(/\D/g, "");
  t = t.replace(/^0+/, "");
  if (t.length === 8) {
    t = "11" + "9" + t;
  } else if (t.length === 9) {
    t = "11" + t;
  } else if (t.length === 10) {
    t = t.replace(/^(\d{2})(\d{8})$/, "$19$2");
  } else if (t.length === 11) {
    t = "55" + t;
  } else if (t.length === 12) {
    t = t.slice(0, 4) + "9" + t.slice(4);
  } else if (t.length > 13) {
    t = t.slice(-13);
  }
  return t;
})($('Loop Over Items').first().json.telefone)
}}

